  (* [comment removed for export] *)
  Definition blockish (L : list block) (iv : Z * Z) : Prop :=
    exists p b n, In (p, b, n) L /\ ((b <= fst iv /\ snd iv <= b + n) \/ (sh b <= fst iv /\ snd iv <= sh b + nsh n)).

  Lemma blockish_blk : forall L p b n l h, In (p, b, n) L -> b <= l -> h <= b + n -> blockish L (l, h).
  Proof. intros. exists p, b, n. cbn. split; [assumption| left; lia]. Qed.
  Lemma blockish_sh : forall L p b n l h, In (p, b, n) L -> sh b <= l -> h <= sh b + nsh n -> blockish L (l, h).
  Proof. intros. exists p, b, n. cbn. split; [assumption| right; lia]. Qed.
  Lemma blockish_blkX : forall L p b n, In (p, b, n) L -> Forall (blockish L) (blkX b n).
  Proof.
    intros L p b n IN. unfold blkX. apply Forall_cons; [eapply blockish_blk; [exact IN| lia| lia]|].
    apply Forall_cons; [eapply blockish_sh; [exact IN| lia| lia]| apply Forall_nil].
  Qed.
