  Lemma Forall_blockish_lo : forall s L m X LF ff fp, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv /\ snd iv <= aceil) X.
  Proof.
    intros s L m X LF ff fp RH FF FB FL. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (K1 & K2 & _). split; [exact K1| exact K2].
  Qed.
  Lemma Forall_blockish_fr : forall s L m X LF ff fp O n, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> ff <= O -> O + n <= ff + 1024 ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X.
  Proof.
    intros s L m X LF ff fp O n RH FF FB FL H1 H2. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & K & _). lia.
  Qed.
  Lemma Forall_blockish_frsh : forall s L m X LF ff fp O n, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> sh ff <= O -> O + n <= sh ff + 128 ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X.
  Proof.
    intros s L m X LF ff fp O n RH FF FB FL H1 H2. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & _ & K & _). lia.
  Qed.
  Lemma Forall_blockish_fp : forall s L m X LF ff fp, as_RHEAP H s L m -> fresh_frame H LF 4 ff fp -> Forall (blockish L) X ->
    Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) X.
  Proof.
    intros s L m X LF ff fp RH FF FB FL. induction X as [|iv X IH]; [apply Forall_nil|].
    apply Forall_cons; [| exact (IH (Forall_inv_tail FB) (Forall_inv_tail FL))].
    pose proof (blockish_facts _ _ _ _ _ _ _ RH FF (Forall_inv FB) (Forall_inv FL)) as (_ & _ & _ & _ & K). exact K.
  Qed.

  (* [comment removed for export] *)
  Definition hz_frame (m : mem) (spa ff fp spv allocb regb schedb stb : Z) (j8 j4 j16 j40 j40b j472 : list byte) (gap saved shd : list cell) : Prop :=
       rw_cells asegs m spa [CB 8 j8; C8 (Z_to_bv 64 ff)]
    /\ rw_cells asegs m (spa + 16) (BasicStreamCells stb)
    /\ rw_cells asegs m (spa + 96) gap /\ Z.of_nat (cells_size gap) = spv + -96 - (spa + 96)
    /\ rw_cells asegs m (spv + -96) saved /\ Z.of_nat (cells_size saved) = 96
    /\ rw_cells asegs m ff (hz_hdr spa ++ [C8 (Z_to_bv 64 AVP_CFGMAKER); C4 (wz 4294967295); CB 4 j4] ++ [CB 16 j16])
    /\ rw_cells asegs m (ff + 88) ([CB 40 j40] ++ [C8 (Z_to_bv 64 allocb); C8 (Z_to_bv 64 regb); C8 (Z_to_bv 64 schedb)] ++ [CB 40 j40b])
    /\ rw_cells asegs m (ff + 544) [CB 472 j472; C8 (Z_to_bv 64 fp)]
    /\ rw_cells asegs m (Z.shiftr ff 3 + 2147450880) shd /\ Z.of_nat (cells_size shd) = 128
    /\ rw_cells asegs m fp [C1 (b8 1)].

  (* [comment removed for export] *)
  Lemma hz_frame_keep : forall s0 L0 m00 s L m0 LF ff fp X XS m m' spa spv allocb regb schedb stb j8 j4 j16 j40 j40b j472 gap saved shd,
    as_RHEAP H s0 L0 m00 -> as_RHEAP H s L m0 -> as_RFS H ((4, ff, fp) :: LF) m -> fresh_frame H LF 4 ff fp ->
    aceil <= spa -> spa + 192 <= spv ->
    Forall (blockish L0) X -> Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fs_scratch H ((4, ff, fp) :: LF)) XS ->
    xpres H L spa (X ++ XS) m m' ->
    hz_frame m spa ff fp spv allocb regb schedb stb j8 j4 j16 j40 j40b j472 gap saved shd ->
    hz_frame m' spa ff fp spv allocb regb schedb stb j8 j4 j16 j40 j40b j472 gap saved shd.
  Proof.
    intros until shd. intros RH0 RH RF FF CEIL SPV FB FL FXS XP (LOC & BS & GAP & GSZ & SAVED & SSZ & FRMh & FRMi & FRMB & SHD & SHSZ & FLG).
    pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & F3' & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
    fs_nums_in F2. pose proof aceil_facts as (AF1 & _).
    pose proof (Forall_blockish_lo _ _ _ _ _ _ _ RH0 FF FB FL) as XLO.
    assert (XST : Forall (fun iv : Z * Z => snd iv <= aceil) (X ++ XS)).
    { apply Forall_app. split.
      - eapply Forall_impl; [| exact XLO]. intros iv [_ K]. exact K.
      - eapply Forall_impl; [| exact FXS]. intros iv K0. pose proof (scratch_facts H HH _ _ [] iv RF K0) as (_ & _ & K3). exact K3. }
    assert (STK : forall O cs, spa <= O -> rw_cells asegs m O cs -> rw_cells asegs m' O cs).
    { intros O cs HO RC. eapply (xpres_rw_cells H); [exact XP| exact RC| split; [left; exact HO|]].
      eapply Forall_impl; [| exact XST]. intros [l h'] Q. cbn [fst snd] in *. clear - Q HO CEIL. lia. }
    assert (FRK : forall O cs, ff <= O -> O + Z.of_nat (cells_size cs) <= ff + 1024 -> rw_cells asegs m O cs -> rw_cells asegs m' O cs).
    { intros O cs H1 H2 RC. eapply (xpres_rw_cells H); [exact XP| exact RC|].
      eapply (xclient_range_aobj H HH); [exact RH| exact RF| eapply aobj_frame; [left; reflexivity| cbn; exact H1| cbn; fs_nums; exact H2]| clear; lia| | exact FXS].
      eapply Forall_blockish_fr; [exact RH0| exact FF| exact FB| exact FL| exact H1| exact H2]. }
    split; [apply STK; [clear; lia| exact LOC]|]. split; [apply STK; [clear; lia| exact BS]|].
    split; [apply STK; [clear; lia| exact GAP]|]. split; [exact GSZ|]. split; [apply STK; [clear - SPV; lia| exact SAVED]|]. split; [exact SSZ|].
    split; [apply FRK; [clear; lia| unfold hz_hdr; cbn; clear; lia| exact FRMh]|].
    split; [apply FRK; [clear; lia| cbn; clear; lia| exact FRMi]|].
    split; [apply FRK; [clear; lia| cbn; clear; lia| exact FRMB]|].
    split; [| split; [exact SHSZ|]].
    - eapply (xpres_rw_cells H); [exact XP| exact SHD|]. rewrite SHSZ. split.
      + eapply (ffsh_client_range H _ _ _ _ _ _ _ _ FF); [clear; lia| fs_nums; clear; lia].
      + rewrite SHFF. apply Forall_app. split.
        * eapply Forall_blockish_frsh; [exact RH0| exact FF| exact FB| exact FL| clear; lia| clear; lia].
        * pose proof (Forall_scratch_sh H HH _ m XS ff 1024 RF (aobj_fsobj H HH _ _ _ _ _ _ RH (aobj_frame L ((4, ff, fp) :: LF) (4, ff, fp) ff 1024 ltac:(left; reflexivity) ltac:(cbn; clear; lia) ltac:(cbn; fs_nums; clear; lia)))
                        ltac:(clear; lia) ltac:(clear - F2 AF1; unfold AAPP_HI; lia) APF FXS) as K0.
          eapply Forall_impl; [| exact K0]. intros [l h'] Q. cbn in *. change (nsh 1024) with 128 in Q. clear - Q. lia.
    - eapply (xpres_rw_cells H); [exact XP| exact FLG|]. split; [eapply (fp_client_range H _ _ _ _ _ _ FF)|].
      cbn [cells_size csize Nat.add]. apply Forall_app. split.
      + eapply Forall_blockish_fp; [exact RH0| exact FF| exact FB| exact FL].
      + eapply (live_flag_off_scratch_gen H HH); [exact RF| left; reflexivity| exact FXS].
  Qed.

  (* [comment removed for export] *)
  Lemma hz_statics_keep : forall s0 L0 m00 L LF ff fp X XS m m' spa errv,
    as_RHEAP H s0 L0 m00 -> as_RFS H ((4, ff, fp) :: LF) m -> fresh_frame H LF 4 ff fp ->
    Forall (blockish L0) X -> Forall (fun iv : Z * Z => fst iv < snd iv) X -> Forall (fs_scratch H ((4, ff, fp) :: LF)) XS ->
    xpres H L spa (X ++ XS) m m' ->
    AXImg m /\ acanary m /\ AHStat FT m /\ rw_cells asegs m AERRNO [C4 errv] ->
    AXImg m' /\ acanary m' /\ AHStat FT m' /\ rw_cells asegs m' AERRNO [C4 errv].
  Proof.
    intros until errv. intros RH RF FF FB FL FXS XP (XI & CA & HS & ERR).
    pose proof (Forall_blockish_lo _ _ _ _ _ _ _ RH FF FB FL) as XLO.
    assert (FLO : Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) (X ++ XS)).
    { apply Forall_app. split; [| exact (scratch_lo H HH _ _ _ RF FXS)]. eapply Forall_impl; [| exact XLO]. intros iv [K _]. exact K. }
    split; [exact (AXImg_xpres_lo H _ _ _ _ _ XI XP FLO)|]. split; [exact (acanary_xpres_lo H _ _ _ _ _ CA XP FLO)|]. split.
    - eapply (AHStat_local FT FT_local); [exact HS|]. intros a Ha.
      assert (XC : xclient H L spa (X ++ XS) a).
      { split; [right; left; unfold aimg_client, AXH_LO, AXH_HI in *; clear - Ha; lia|].
        apply not_rin_lo; [exact FLO|]. unfold AXH_LO, AXH_HI, AIMG_TOP in Ha |- *. clear - Ha. lia. }
      exact (proj1 (XP a ltac:(unfold AXH_LO, AXH_HI in Ha; clear - Ha; lia) XC)).
    - eapply (xpres_rw_cells H); [exact XP| exact ERR|]. cbn [cells_size csize Nat.add].
      split; [right; left; intros a' Ha'; unfold aimg_client, AERRNO, ATP in *; clear - Ha'; lia|].
      eapply Forall_impl; [| exact FLO]. intros [l h'] Q. cbn [fst snd] in *. left. unfold AERRNO, ATP, AIMG_TOP in *. clear - Q. lia.
  Qed.
  (* [comment removed for export] *)
  Lemma ARegistry_set_first : forall LB m m' r owner first first' lk,
    ARegistry LB m r owner first lk -> munch [(r + 56, r + 64)]%Z m m' -> wmono asegs m m' ->
    rw_cells asegs m' (r + O_REG_OWNER) [C8 (wz owner); C8 (wz first')] -> ARegistry LB m' r owner first' lk.
  Proof.
    intros LB m m' r owner first first' lk (p & j0 & j7 & IN & C0 & PM & C1 & C2 & RB & AD) MU WM ROF. exists p, j0, j7.
    pose proof (rblock_bounds _ _ RB) as (R0 & _ & R2 & _).
    pose proof (sh_nsh_high r NEWSZ_REG R0 ltac:(unfold NEWSZ_REG; lia) R2) as W9. pose proof (aapp_not_shadowland _ _ (proj1 (proj2 (proj2 (proj2 RB))))) as NS.
    pose proof (sh_mono 0 r R0) as M0. change (sh 0) with 2147450880 in M0.
    assert (AD' : addressable m' r NEWSZ_REG).
    { eapply addressable_transport; [exact AD| exact MU| exact WM|]. cbn [disjoint_from fst snd]. unfold NEWSZ_REG, ALOWSH_LO, AHI_LO in *. lia. }
    unfold NEWSZ_REG, O_REG_MUTEX, O_REG_OWNER, SZ_REG, CookieCells, zeros in *.
    split; [exact IN|].
    split. { eapply rw_cells_transport; [exact C0| exact MU| exact WM| cbn; lia]. }
    split. { eapply APMutex_transport; [exact PM| exact MU| exact WM| cbn; unfold SZ_PMUTEX; lia]. }
    split; [exact ROF|]. split. { eapply rw_cells_transport; [exact C2| exact MU| exact WM| cbn; lia]. }
    split; [exact RB| exact AD'].
  Qed.

  (* [comment removed for export] *)
  Lemma ARegistry_glue : forall s LB m r owner first lk, as_RHEAP H s LB m -> ARegistry LB m r owner first lk ->
    rw_cells asegs m (r + O_REG_OWNER) [C8 (wz owner); C8 (wz first)] /\ addressable m r NEWSZ_REG /\ 0 < r /\ r + NEWSZ_REG <= aceil
    /\ r mod 16 = 0 /\ aapp r NEWSZ_REG /\ (exists p, In (p, r, NEWSZ_REG) LB).
  Proof.
    intros s LB m r owner first lk RH (p & j0 & j7 & IN & C0 & PM & C1 & C2 & RB & AD).
    pose proof RB as (R1 & R2 & _ & R4 & R5). split; [exact C1|]. split; [exact AD|]. repeat (split; [assumption|]). exists p. exact IN.
  Qed.
